import SwiftUI

// MARK: - Editorial Type Scale

public enum Typography {
    // MARK: Display

    /// Masthead — 44pt serif bold. App name / section front.
    public static let masthead = Font.system(size: 44, weight: .bold, design: .serif)
    /// Headline — 28pt serif semibold. Meeting title in list.
    public static let headline = Font.system(size: 28, weight: .semibold, design: .serif)
    /// Subhead — 20pt serif medium. Column headers.
    public static let subhead = Font.system(size: 20, weight: .medium, design: .serif)
    /// Deck — 16pt serif italic. Summary lead-in below headline.
    public static let deck = Font.system(size: 16, weight: .regular, design: .serif).italic()

    // MARK: Body

    /// Body — 15pt serif. Transcript and summary prose.
    public static let body = Font.system(size: 15, weight: .regular, design: .serif)
    /// Body emphasis — 15pt serif semibold. Speaker label in transcript turn.
    public static let bodyEm = Font.system(size: 15, weight: .semibold, design: .serif)
    /// Body italic — 15pt serif italic. Pullquote source attribution.
    public static let bodyItalic = Font.system(size: 15, weight: .regular, design: .serif).italic()
    /// Pull quote — 18pt serif medium italic. Summary drop-in callouts.
    public static let pullQuote = Font.system(size: 18, weight: .medium, design: .serif).italic()

    // MARK: Chrome

    /// UI label — 13pt sans medium. Button labels, nav items.
    public static let uiLabel = Font.system(size: 13, weight: .medium, design: .default)
    /// UI small — 11pt sans. Secondary meta, badges.
    public static let uiSmall = Font.system(size: 11, weight: .regular, design: .default)
    /// Byline — 11pt sans italic. Author / speaker attribution.
    public static let bylineFont = Font.system(size: 11, weight: .regular, design: .default).italic()

    // MARK: Data / editorial marks

    /// Kicker — 10pt mono semibold. Section label (uppercased, tracked).
    public static let kicker = Font.system(size: 10, weight: .semibold, design: .monospaced)
    /// Folio — 9pt mono medium. Edition / page footer.
    public static let folio = Font.system(size: 9, weight: .medium, design: .monospaced)
    /// Timer — 22pt mono medium. Recording elapsed time.
    public static let timer = Font.system(size: 22, weight: .medium, design: .monospaced)
    /// Timestamp — 10pt mono. Transcript turn timestamps.
    public static let timestamp = Font.system(size: 10, weight: .regular, design: .monospaced)
}

// MARK: - View Modifier Extensions

public extension View {
    /// Applies kicker style: mono semibold 10pt, 1.8pt tracking, uppercased,
    /// ink3 foreground — used for section labels throughout Broadsheet.
    func kicker() -> some View {
        font(Typography.kicker)
            .tracking(1.8)
            .textCase(.uppercase)
            .foregroundStyle(Color.ink3)
    }

    /// Applies folio style: mono medium 9pt, 1.4pt tracking, uppercased,
    /// ink3 foreground — used for edition / page footers.
    func folio() -> some View {
        font(Typography.folio)
            .tracking(1.4)
            .textCase(.uppercase)
            .foregroundStyle(Color.ink3)
    }

    /// Applies byline style: sans italic 11pt, ink2 foreground —
    /// used for speaker attribution and metadata lines.
    func byline() -> some View {
        font(Typography.bylineFont)
            .foregroundStyle(Color.ink2)
    }
}

