    public static let sidebar: CGFloat = 240
    /// Meeting list column — 320pt.
    public static let listColumn: CGFloat = 320

    // MARK: Corner radii

    /// Card corner radius — 0pt (newspaper: sharp corners everywhere).
    public static let radiusCard: CGFloat = 0
    /// Window corner radius — 0pt.
    public static let radiusWindow: CGFloat = 0
    /// Pill / badge corner radius — 2pt (minimal softening for legibility).
    public static let radiusPill: CGFloat = 2

    // MARK: Rule weights

    /// Hairline rule — 0.5pt. Column separators.
    public static let hairline: CGFloat = 0.5
    /// Standard rule — 1pt. Section dividers.
    public static let rule: CGFloat = 1
    /// Heavy rule — 2pt. Folio strip top, section fronts.
