import SwiftUI
import AppKit
import Domain
import Logging
import Business
import AudioInfrastructure
import MLInfrastructure
import Presentation

/// The top-level SwiftUI application entry point for THE RECORD.
@main
public struct TheRecordApp: App {
    /// The application delegate managing the status bar, popover, and composition root.
    @NSApplicationDelegateAdaptor(AppDelegate.self) public var appDelegate

    private let speakerProfileStore = JSONSpeakerProfileStore()

    public init() {}

    public var body: some Scene {
        Window("THE RECORD", id: "main") {
            AppContentView(appDelegate: appDelegate)
                .environment(appDelegate.appState)
        }
        .commands {
            CommandGroup(after: .appInfo) {
                Button("Third-Party Licenses") {
                    if let url = Bundle.main.url(forResource: "ThirdPartyLicenses", withExtension: "txt") {
                        NSWorkspace.shared.open(url)
                    }
                }
            }
            CommandGroup(after: .newItem) {
                Button("New Meeting") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.startRecordingTapped()
                    }
                }
                .keyboardShortcut("n", modifiers: .command)
                .disabled(appDelegate.menuBarVM?.isRecording == true)
                Divider()
                Button("Stop Recording") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.stopRecordingTapped()
                    }
                }
                .keyboardShortcut(".", modifiers: .command)
                Divider()
                Button("Re-transcribe from Audio") {
                    Task { @MainActor in
                        if let id = appDelegate.menuBarVM?.cleanupRecordingId {
                            _ = await appDelegate.menuBarVM?.runCleanupPass(recordingId: id)
                        }
                    }
                }
                .keyboardShortcut("r", modifiers: [.command, .shift])
                .disabled(appDelegate.menuBarVM?.cleanupRecordingId == nil || appDelegate.menuBarVM?
                    .isRecording == true)
            }
        }
        Settings {
            if let appState = appDelegate.appState {
                SettingsView(
                    viewModel: SettingsViewModel(
                        appState: appState,
                        profileStore: speakerProfileStore,
                        audioDeviceConfigStore: AudioDeviceConfigStoreImpl(configManager: appDelegate.sharedConfigManager),
                        deviceEnumeration: AudioDeviceEnumerator()
                    ),
                    modelDownloadViewModel: ModelDownloadViewModel(
                        downloadWhisper: { modelId, token in
                            let typedModelId = ModelID(modelId)
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await WhisperKitPlugin().loadModel(typedModelId)
                        },
                        downloadParakeet: { modelId, token in
                            let typedModelId = ModelID(modelId)
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await ParakeetPlugin().loadModel(typedModelId)
                        },
                        downloadMLX: { modelId, token in
                            let config = SummaryConfig(
                                modelId: ModelID(modelId),
                                maxTokens: SummaryConfig.default.maxTokens,
                                temperature: SummaryConfig.default.temperature,
                                enabled: true,
                                meetingType: SummaryConfig.default.meetingType,
                            )
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await MLXSummarizationPlugin().loadModel(config)
                        },
                        downloadDiarization: {
                            try await FluidDiarizationPlugin().prepare()
                        },
                        tokenStore: HFTokenKeychain(),
                    )
                )
            } else {
                ProgressView()
            }
        }
    }
}

// MARK: - Root Content View

struct AppContentView: View {
    var appDelegate: AppDelegate
    @Environment(AppState.self) private var appState: AppState?

    // AudioPlayerViewModel is owned here and passed into MainWindowView so
    // Presentation never needs to import AVFoundation or Infrastructure directly.
    @State private var audioPlayerVM = AudioPlayerViewModel(driver: AVPlayerDriver())

    var body: some View {
        if let appState,
           let menuBarVM = appDelegate.menuBarVM,
           let libraryVM = appDelegate.libraryVM,
           let searchVM = appDelegate.searchVM,
           let detailVM = appDelegate.detailVM,
           let commitmentsVM = appDelegate.commitmentsVM,
           let waveformVM = menuBarVM.waveformVM {

            switch appState.settings.uiTheme {
            case .broadsheet:
                if let broadsheetAppState = appDelegate.broadsheetAppState {
                    BroadsheetRootView(
                        appState: broadsheetAppState,
                        permissionService: SystemPermissionService(),
                    )
                }
            case .classic:
                MainWindowView(
                    menuBarVM: menuBarVM,
                    libraryVM: libraryVM,
                    searchVM: searchVM,
                    detailVM: detailVM,
                    waveformVM: waveformVM,
                    commitmentsVM: commitmentsVM,
                    audioPlayerVM: audioPlayerVM,
                )
            }
        } else {
            ProgressView("Starting THE RECORD...")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

// MARK: - App Delegate

@Observable
@MainActor
public final class AppDelegate: NSObject, NSApplicationDelegate {

    public var statusItem: NSStatusItem?
    public var popover: NSPopover?

    private let assembler = AppAssembler()

    // SSOT Root
    public private(set) var appState: AppState?

    // Legacy Bridge Properties
    public private(set) var uiTheme: UITheme = .default
    public private(set) var defaultEngine: TranscriptionEngineKey = TranscriptionConfig.default.defaultEngine
    public private(set) var archivePassEnabled: Bool = TranscriptionConfig.default.archivePassEnabled
    public private(set) var libraryVM: MeetingLibraryViewModel?
    public private(set) var menuBarVM: MenuBarViewModel?
    public private(set) var searchVM: SearchViewModel?
    public private(set) var detailVM: MeetingDetailViewModel?
    public private(set) var commitmentsVM: CommitmentsViewModel?
    public private(set) var broadsheetAppState: BroadsheetAppState?
    public private(set) var contextSuggestionsVM: ContextSuggestionsViewModel?

    private let logger = AppLogger.for(category: "AppDelegate")
    public let sharedConfigManager = ConfigManager()

    private var themeObserver: NSObjectProtocol?
    private var privacyModeObserver: NSObjectProtocol?
    private var engineObserver: NSObjectProtocol?
    private var archivePassEnabledObserver: NSObjectProtocol?
    private var recordingStartObserver: NSObjectProtocol?
    private var recordingStopObserver: NSObjectProtocol?
    private var windowKeyObserver: NSObjectProtocol?
    private var currentPrivacyMode: PrivacyMode = .default

    public func applicationDidFinishLaunching(_ notification: Notification) {
        let launchConfig = AppConfig.default
        uiTheme = launchConfig.uiTheme
        defaultEngine = launchConfig.transcription.defaultEngine
        archivePassEnabled = launchConfig.transcription.archivePassEnabled
        currentPrivacyMode = launchConfig.privacyMode

        setupConfigObservers()

        Task { @MainActor in
            let assembled = await assembler.assemble(config: launchConfig)
            self.appState = assembled.appState

            // Sync legacy properties
            self.menuBarVM = assembled.menuBarVM
            self.libraryVM = assembled.libraryVM
            self.searchVM = assembled.searchVM
            self.detailVM = assembled.detailVM
            self.commitmentsVM = assembled.commitmentsVM
            self.contextSuggestionsVM = assembled.contextSuggestionsVM

            let appState = assembled.appState
            self.broadsheetAppState = BroadsheetAppState(
                appState: appState,
                menuBarVM: assembled.menuBarVM,
                libraryVM: assembled.libraryVM,
                detailVM: assembled.detailVM,
                commitmentsVM: assembled.commitmentsVM
            )

            self.setupStatusBar(viewModel: assembled.menuBarVM)
        }

        windowKeyObserver = NotificationCenter.default.addObserver(
            forName: NSWindow.didBecomeKeyNotification,
            object: nil,
            queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: self.menuBarVM?.isRecording ?? false)
            }
        }

        logger.info("THE RECORD launched")
    }

    public func applicationWillTerminate(_ notification: Notification) {
        assembler.teardown()
    }

    private func setupConfigObservers() {
        themeObserver = NotificationCenter.default.addObserver(
            forName: .themeChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let theme = note.userInfo?["uiTheme"] as? UITheme else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.uiTheme = theme
                self.appState?.settings.uiTheme = theme
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: current.transcription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: theme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist theme: \(error, privacy: .public)")
                    }
                }
            }
        }

        privacyModeObserver = NotificationCenter.default.addObserver(
            forName: .privacyModeChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let raw = note.userInfo?["privacyMode"] as? String,
                  let mode = PrivacyMode(rawValue: raw)
            else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.currentPrivacyMode = mode
                self.appState?.settings.privacyMode = mode
                self.applyPrivacyMode(mode, isRecording: self.menuBarVM?.isRecording ?? false)
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: current.transcription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: mode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist privacy mode: \(error, privacy: .public)")
                    }
                }
            }
        }

        engineObserver = NotificationCenter.default.addObserver(
            forName: .engineChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let raw = note.userInfo?["defaultEngine"] as? String,
                  let engine = TranscriptionEngineKey(rawValue: raw)
            else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.defaultEngine = engine
                self.appState?.settings.defaultEngine = engine
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let newTranscription = TranscriptionConfig(
                            defaultEngine: engine,
                            fallbackEngine: current.transcription.fallbackEngine,
                            cleanupModelId: current.transcription.cleanupModelId,
                            archivePassEnabled: current.transcription.archivePassEnabled,
                        )
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: newTranscription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist engine selection: \(error, privacy: .public)")
                    }
                }
            }
        }

        archivePassEnabledObserver = NotificationCenter.default.addObserver(
            forName: .archivePassEnabledChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let enabled = note.userInfo?["enabled"] as? Bool else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.archivePassEnabled = enabled
                self.appState?.settings.archivePassEnabled = enabled
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let newTranscription = TranscriptionConfig(
                            defaultEngine: current.transcription.defaultEngine,
                            fallbackEngine: current.transcription.fallbackEngine,
                            cleanupModelId: current.transcription.cleanupModelId,
                            archivePassEnabled: enabled,
                        )
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: newTranscription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist archive pass setting: \(error, privacy: .public)")
                    }
                }
            }
        }

        recordingStartObserver = NotificationCenter.default.addObserver(
            forName: .recordingStarted, object: nil, queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: true)
            }
        }

        recordingStopObserver = NotificationCenter.default.addObserver(
            forName: .recordingStopped, object: nil, queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: false)
            }
        }
    }

    private func setupStatusBar(viewModel: MenuBarViewModel) {
        let item = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
        item.button?.image = NSImage(systemSymbolName: "waveform", accessibilityDescription: "THE RECORD")
        item.button?.action = #selector(togglePopover)
        item.button?.target = self
        statusItem = item

        let pop = NSPopover()
        pop.contentSize = NSSize(width: 320, height: 400)
        pop.behavior = .transient
        pop.contentViewController = NSHostingController(rootView: MenuBarPopover(viewModel: viewModel))
        popover = pop
    }

    private func applyPrivacyMode(_ mode: PrivacyMode, isRecording: Bool) {
        guard let window = NSApp.windows.first else { return }
        let protect: Bool = switch mode {
        case .off: false
        case .always: true
        case .meetings: isRecording
        }
        window.sharingType = protect ? .none : .readOnly
    }

    @objc private func togglePopover() {
        guard let button = statusItem?.button, let pop = popover else { return }
        if pop.isShown {
            pop.performClose(nil)
        } else {
            pop.show(relativeTo: button.bounds, of: button, preferredEdge: .minY)
        }
    }
}

