struct DesignTokensTests {
    /// Broadsheet ink scale
    @Test func inkColorsExist() {
        _ = Color.ink
        _ = Color.ink2
        _ = Color.ink3
        _ = Color.ink4
    }

    @Test func backgroundColorsExist() {
        _ = Color.bg
        _ = Color.paper
        _ = Color.tint
    }

    @Test func broadsheetPaletteExists() {
        _ = Color.newsprint
        _ = Color.rule
        _ = Color.hairlineColor
        _ = Color.highlight
        _ = Color.breaking
        _ = Color.editor
    }

    @Test func hexInitializerProducesDistinctColors() {
        // Verifies the Color(hex:) initializer is public and produces
        // distinct values for distinct hex inputs.
        let black = Color(hex: 0x000000)
        let white = Color(hex: 0xFFFFFF)
        // Colors created from different hex values must not be identical.
        // We use a round-trip through UIColor to get comparable RGBA values.
        let blackNS = NSColor(black).usingColorSpace(.sRGB)
        let whiteNS = NSColor(white).usingColorSpace(.sRGB)
        #expect(blackNS?.redComponent != whiteNS?.redComponent)
    }
}

