    static let ink4 = Color(hex: 0xA8A89E)
    /// Deep ink surface — 0x1E1E1C.
    static let inkDeep = Color(hex: 0x1E1E1C)

    // MARK: Backgrounds

    /// Page fill — newsprint warm off-white 0xF1ECE0.
    static let newsprint = Color(hex: 0xF1ECE0)
    /// Content surface — 0xFBF7EC (use as bg for columns).
    static let bg = Color(hex: 0xFBF7EC)
    /// Warm tinted surface — 0xE8E2D2.
    static let tint = Color(hex: 0xE8E2D2)
    /// Paper — alias for bg (backward compat).
    static let paper = Color(hex: 0xFBF7EC)

    // MARK: Rules & borders

    /// Heavy rule — 0x141412.
    static let rule = Color(hex: 0x141412)
    /// Mid rule — 0xC8C2B0.
    static let midRule = Color(hex: 0xC8C2B0)
    /// Light rule — 0xDDD6C4.
    static let hairlineColor = Color(hex: 0xDDD6C4)

    // MARK: Accent

    /// Selection highlight — yellow 0xFFF1A8.
    static let highlight = Color(hex: 0xFFF1A8)
    /// Breaking / live / stop — red 0xB8281F.
    static let breaking = Color(hex: 0xB8281F)
    /// AI editor marginalia — forest green 0x2D5A3D.
    static let editor = Color(hex: 0x2D5A3D)

    // MARK: Hex initialiser

    /// Creates a `Color` from a 6-digit RGB hex literal, e.g. `Color(hex: 0x0E0E0C)`.
    init(hex: UInt32) {
        let r = Double((hex >> 16) & 0xFF) / 255
        let g = Double((hex >> 8) & 0xFF) / 255
        let b = Double(hex & 0xFF) / 255
        self.init(red: r, green: g, blue: b)
    }
}

// MARK: - Classic skin bridge (zero callsite changes)

/// Typealias bridge so any Classic-skin code that still uses `DesignTokens.ink`
/// continues to compile unchanged.
public enum DesignTokens {
    public static let ink = Color.ink
    public static let ink2 = Color.ink2
    public static let ink3 = Color.ink3
    public static let ink4 = Color.ink4
    public static let bg = Color.bg
    public static let paper = Color.paper
    public static let tint = Color.tint
}
